/// <summary>
/// CB233_TOReceiptDetails custom service header contract
/// </summary>
[DataContractAttribute]
class METInventTransferOrderReceiveHeaderContract
{
    private str     dataAreaId;
    private str     inventTransferId;
    private date    postingDate;

}

Method.Source:
/// <summary>
/// Data area Id
/// </summary>
/// <param name = "_dataAreaId">Set data area Id</param>
/// <returns>Get data area Id</returns>
[DataMember("DataAreaId")]
public str parmDataAreaId(str _dataAreaId = dataAreaId)
{
    if (!prmIsDefault(_dataAreaId))
    {
        dataAreaId = _dataAreaId;
    }
    return dataAreaId;
}

/// <summary>
/// Transfer order Id
/// </summary>
/// <param name = "_inventTransferId">Set transfer order Id</param>
/// <returns>Get transfer order Id</returns>
[DataMemberAttribute('InventTransferId')]
public str parmInventTransferId(str _inventTransferId = inventTransferId)
{
    if (!prmIsDefault(_inventTransferId))
    {
        inventTransferId = _inventTransferId;
    }
    return inventTransferId;
}

/// <summary>
/// TO receipt posting date
/// </summary>
/// <param name = "_postingDate">Set posting date</param>
/// <returns>Get posting date</returns>
[DataMemberAttribute('PostingDate')]
public date parmPostingDate(date _postingDate = postingDate)
{
    if (!prmIsDefault(_postingDate))
    {
        postingDate = _postingDate;
    }
    return postingDate;
}
